import { useEffect, useState } from "react";
import { Table, Spinner, Alert } from "react-bootstrap";

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchOrders();
  }, []);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch("http://localhost/api/comandes");

      if (!response.ok) {
        throw new Error("Error al obtenir les comandes");
      }

      const data = await response.json();

      // ✅ tu API: { exit: true, dades: [...] }
      if (data.exit && Array.isArray(data.dades)) {
        setOrders(data.dades);
      } else {
        setOrders([]);
      }
    } catch (err) {
      console.error(err);
      setError("Error al obtenir les comandes");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
        <p className="mt-2">Carregant comandes...</p>
      </div>
    );
  }

  if (error) {
    return <Alert variant="danger">{error}</Alert>;
  }

  if (orders.length === 0) {
    return <p>No hi ha comandes disponibles.</p>;
  }

  return (
    <div className="mt-4">
      <h2>Comandes</h2>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Data</th>
            <th>Tipus</th>
            <th>Usuari</th>
            <th>Client</th>
            <th>Proveïdor</th>
          </tr>
        </thead>
<tbody>
  {orders.map(order => (
    <tr key={order.id}>
      <td>{order.id}</td>
      <td>{order.data}</td>
      <td>{order.tipus}</td>

      <td>
        {order.client ? order.client.nom : "—"}
      </td>

      <td>
        {order.proveidor ? order.proveidor.nom : "—"}
      </td>
    </tr>
  ))}
</tbody>

      </Table>
    </div>
  );
}

export default OrdersList;
